// clusterSession contains authenticated user session to the target cluster:
// x509 short lived credentials, forwarding proxies and other data
type clusterSession struct {
	authContext
	parent    *Forwarder
	creds     *kubeCreds
	tlsConfig *tls.Config
	forwarder *forward.Forwarder
	// kubeAddress is the address selected for this session.
	kubeAddress string
	// noAuditEvents is true if this teleport service should leave audit event
	// logging to another service.
	noAuditEvents bool
}

func (s *clusterSession) monitorConn(conn net.Conn, err error) (net.Conn, error) {
	if err != nil {
		return nil, trace.Wrap(err)
	}

	ctx, cancel := context.WithCancel(s.parent.ctx)
	tc, err := srv.NewTrackingReadConn(srv.TrackingReadConnConfig{
		Conn:    conn,
		Clock:   s.parent.cfg.Clock,
		Context: s.parent.cfg.Context,
		Cancel:  cancel,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = srv.StartMonitor(srv.MonitorConfig{
		LockWatcher:           s.parent.cfg.LockWatcher,
		LockTargets:           s.LockTargets(),
		DisconnectExpiredCert: s.disconnectExpiredCert,
		ClientIdleTimeout:     s.clientIdleTimeout,
		Clock:                 s.parent.cfg.Clock,
		Tracker:               tc,
		Conn:                  tc,
		Context:               ctx,
		TeleportUser:          s.User.GetName(),
		ServerID:              s.parent.cfg.ServerID,
		Entry:                 s.parent.log,
		Emitter:               s.parent.cfg.AuthClient,
	})
	if err != nil {
		tc.Close()
		return nil, trace.Wrap(err)
	}
	return tc, nil
}

func (s *clusterSession) Dial(network, addr string) (net.Conn, error) {
	return s.monitorConn(s.teleportCluster.DialWithContext(context.Background(), network, addr))
}

func (s *clusterSession) DialWithContext(ctx context.Context, network, addr string) (net.Conn, error) {
	return s.monitorConn(s.teleportCluster.DialWithContext(ctx, network, addr))
}

func (s *clusterSession) DialWithEndpoints(network, addr string) (net.Conn, error) {
	return s.monitorConn(s.dial(context.Background(), network, addr))
}

// dial connects to the endpoint selected for this session.
func (s *clusterSession) dial(ctx context.Context, network, addr string) (net.Conn, error) {
	if len(s.teleportClusterEndpoints) == 0 {
		return nil, trace.BadParameter("no endpoints to dial")
	}
	endpoint := kubeClusterEndpoint{addr: s.kubeAddress, serverID: s.teleportCluster.serverID}
	if endpoint.addr == "" {
		endpoint = s.teleportClusterEndpoints[mathrand.Intn(len(s.teleportClusterEndpoints))]
		s.kubeAddress = endpoint.addr
		s.teleportCluster.targetAddr = endpoint.addr
		s.teleportCluster.serverID = endpoint.serverID
	}
	return s.teleportCluster.dialEndpoint(ctx, network, endpoint)
}

// dialWithEndpoints is retained for callers that dial without monitoring.
func (s *clusterSession) dialWithEndpoints(ctx context.Context, network, addr string) (net.Conn, error) {
	return s.dial(ctx, network, addr)
}

