// dial tries the selected endpoint first, then the other registered endpoints.
func (s *clusterSession) dial(ctx context.Context, network, addr string) (net.Conn, error) {
	if len(s.teleportClusterEndpoints) == 0 {
		return nil, trace.BadParameter("no endpoints to dial")
	}
	start := 0
	for i, endpoint := range s.teleportClusterEndpoints {
		if endpoint.addr == s.kubeAddress && endpoint.serverID == s.teleportCluster.serverID {
			start = i
			break
		}
	}
	var errs []error
	for i := range s.teleportClusterEndpoints {
		endpoint := s.teleportClusterEndpoints[(start+i)%len(s.teleportClusterEndpoints)]
		conn, err := s.teleportCluster.dialEndpoint(ctx, network, endpoint)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		s.kubeAddress = endpoint.addr
		s.teleportCluster.targetAddr = endpoint.addr
		s.teleportCluster.serverID = endpoint.serverID
		return conn, nil
	}
	return nil, trace.NewAggregate(errs...)
}

// dialWithEndpoints is retained for callers that dial without monitoring.
func (s *clusterSession) dialWithEndpoints(ctx context.Context, network, addr string) (net.Conn, error) {
	return s.dial(ctx, network, addr)
}

